const reserva = $('Normalizar borrador para retención').first().json;

const respuestaAgua = reserva.requiere_agua
  ? $('Revalidar agua para retención').first().json
  : {};

const respuestaTerapeutas = reserva.requiere_terapeuta
  ? $('Revalidar terapeutas para retención').first().json
  : {};

function texto(valor) {
  return String(valor ?? '').trim();
}

function idNormalizado(valor) {
  if (valor && typeof valor === 'object') {
    valor =
      valor.employee_id ??
      valor.resource_id ??
      valor.recurso_id ??
      valor.id ??
      '';
  }

  return texto(valor);
}

function unicos(valores) {
  return [
    ...new Set(
      (valores || [])
        .map(idNormalizado)
        .filter(Boolean)
    ),
  ];
}

function extraerHora(valor) {
  const match = texto(valor).match(
    /(?:^|T|\s)(\d{1,2}):(\d{2})(?::\d{2})?/
  );

  if (!match) return null;

  return (
    String(Number(match[1])).padStart(2, '0') +
    ':' +
    match[2]
  );
}

function estaActivo(valor) {
  if (valor === false || valor === 0 || valor === null) return false;

  const normalizado = texto(valor).toLowerCase();

  return ![
    'false',
    '0',
    'unavailable',
    'ocupado',
    'no_disponible',
  ].includes(normalizado);
}

/*
 * Pabau puede devolver los horarios como:
 * - ["11:00", "11:20"]
 * - {"11:00": true}
 * - [{"time": "11:00"}]
 * - [{"start": "2026-09-12T11:00:00"}]
 *
 * Esta función admite las cuatro variantes sin confundir IDs o fechas.
 */
function contieneHora(valor, horaBuscada, profundidad = 0) {
  if (valor === undefined || valor === null || profundidad > 8) {
    return false;
  }

  if (Array.isArray(valor)) {
    return valor.some((item) =>
      contieneHora(item, horaBuscada, profundidad + 1)
    );
  }

  if (typeof valor === 'object') {
    const camposHora = [
      valor.time,
      valor.hora,
      valor.start,
      valor.start_time,
      valor.startTime,
      valor.slot,
      valor.datetime,
      valor.date_time,
    ];

    if (
      camposHora.some(
        (campo) => extraerHora(campo) === horaBuscada
      ) &&
      estaActivo(
        valor.available ??
        valor.disponible ??
        valor.enabled ??
        valor.status ??
        true
      )
    ) {
      return true;
    }

    return Object.entries(valor).some(([clave, contenido]) => {
      if (
        extraerHora(clave) === horaBuscada &&
        estaActivo(contenido)
      ) {
        return true;
      }

      return contieneHora(
        contenido,
        horaBuscada,
        profundidad + 1
      );
    });
  }

  return extraerHora(valor) === horaBuscada;
}

function buscarAvailableDates(valor, profundidad = 0) {
  if (!valor || typeof valor !== 'object' || profundidad > 8) {
    return null;
  }

  if (Array.isArray(valor)) {
    for (const item of valor) {
      const encontrado = buscarAvailableDates(item, profundidad + 1);
      if (encontrado) return encontrado;
    }

    return null;
  }

  if (
    valor.available_dates &&
    typeof valor.available_dates === 'object'
  ) {
    return valor.available_dates;
  }

  for (const contenido of Object.values(valor)) {
    const encontrado = buscarAvailableDates(
      contenido,
      profundidad + 1
    );

    if (encontrado) return encontrado;
  }

  return null;
}

function mapaDeFecha(availableDates, fecha) {
  if (!availableDates || typeof availableDates !== 'object') {
    return null;
  }

  if (Object.prototype.hasOwnProperty.call(availableDates, fecha)) {
    return availableDates[fecha];
  }

  const clave = Object.keys(availableDates).find(
    (candidate) => texto(candidate).slice(0, 10) === fecha
  );

  return clave ? availableDates[clave] : null;
}

function camposId(valor) {
  if (!valor || typeof valor !== 'object' || Array.isArray(valor)) {
    return [];
  }

  return [
    valor.employee_id,
    valor.employeeId,
    valor.resource_id,
    valor.resourceId,
    valor.recurso_id,
    valor.id,
  ]
    .map(idNormalizado)
    .filter(Boolean);
}

/* Busca los horarios que pertenecen a UN recurso concreto. */
function horariosDelRecurso(valor, recursoId, profundidad = 0) {
  if (!valor || typeof valor !== 'object' || profundidad > 8) {
    return undefined;
  }

  const id = idNormalizado(recursoId);

  if (!id) return undefined;

  if (!Array.isArray(valor)) {
    if (Object.prototype.hasOwnProperty.call(valor, id)) {
      return valor[id];
    }

    if (camposId(valor).includes(id)) {
      return (
        valor.slots ??
        valor.available_slots ??
        valor.available_times ??
        valor.times ??
        valor.horarios ??
        valor.availability ??
        valor
      );
    }
  }

  const contenidos = Array.isArray(valor)
    ? valor
    : Object.values(valor);

  for (const contenido of contenidos) {
    const encontrado = horariosDelRecurso(
      contenido,
      id,
      profundidad + 1
    );

    if (encontrado !== undefined) return encontrado;
  }

  return undefined;
}

function idsDevueltos(valor, salida = new Set(), profundidad = 0) {
  if (!valor || typeof valor !== 'object' || profundidad > 8) {
    return [...salida];
  }

  if (!Array.isArray(valor)) {
    for (const clave of Object.keys(valor)) {
      if (/^\d{4,}$/.test(clave)) salida.add(clave);
    }

    for (const id of camposId(valor)) salida.add(id);
  }

  for (const contenido of Object.values(valor)) {
    idsDevueltos(contenido, salida, profundidad + 1);
  }

  return [...salida];
}

function horasDevueltas(valor, salida = new Set(), profundidad = 0) {
  if (valor === undefined || valor === null || profundidad > 8) {
    return [...salida];
  }

  if (Array.isArray(valor)) {
    for (const contenido of valor) {
      horasDevueltas(contenido, salida, profundidad + 1);
    }

    return [...salida];
  }

  if (typeof valor === 'object') {
    for (const [clave, contenido] of Object.entries(valor)) {
      const horaClave = extraerHora(clave);
      if (horaClave && estaActivo(contenido)) salida.add(horaClave);

      horasDevueltas(contenido, salida, profundidad + 1);
    }

    return [...salida];
  }

  const hora = extraerHora(valor);
  if (hora) salida.add(hora);

  return [...salida];
}

const fechasAgua = reserva.requiere_agua
  ? buscarAvailableDates(respuestaAgua)
  : {};

const fechasTerapeutas = reserva.requiere_terapeuta
  ? buscarAvailableDates(respuestaTerapeutas)
  : {};

if (reserva.requiere_agua && !fechasAgua) {
  throw new Error(
    'Pabau no devolvió available_dates para el componente de agua. ' +
    'No se creó ninguna cita.'
  );
}

if (reserva.requiere_terapeuta && !fechasTerapeutas) {
  throw new Error(
    'Pabau no devolvió available_dates para terapeutas. ' +
    'No se creó ninguna cita.'
  );
}

let recursosSeleccionados = [];
let terapeutasSeleccionados = [];
let terapeutasReemplazados = [];
let diagnosticoAgua = null;

if (reserva.requiere_agua) {
  const fechaAgua = texto(reserva.jacuzzi_inicio).slice(0, 10);
  const horaAgua = texto(reserva.jacuzzi_inicio).slice(11, 16);
  const mapaAgua = mapaDeFecha(fechasAgua, fechaAgua);

  if (!mapaAgua) {
    throw new Error(
      'Pabau no devolvió la fecha de agua ' + fechaAgua +
      '. Fechas recibidas: ' +
      Object.keys(fechasAgua || {}).join(', ')
    );
  }

  const disponibleAgua = (id) => {
    const horarios = horariosDelRecurso(mapaAgua, id);
    return horarios !== undefined && contieneHora(horarios, horaAgua);
  };

  const esTemazcal =
    reserva.tipo_recurso_agua === 'TEMAZCAL' ||
    texto(reserva.servicio).startsWith('temazcal_bliss') ||
    texto(reserva.servicio) === 'temazcal';

  if (reserva.tipo_recurso_agua==='SAUNA' || texto(reserva.servicio).startsWith('elephant_glow_')) {
    if(reserva.sucursal!=='24079'||!disponibleAgua('151614'))throw new Error('El sauna 151614 de Polanco no está disponible a la hora solicitada. No se sustituye por jacuzzi.');
    recursosSeleccionados=['151614'];
    diagnosticoAgua={tipo:'SAUNA',recurso_solicitado:'151614',fecha_solicitada:fechaAgua,hora_solicitada:horaAgua};
  } else if (esTemazcal) {
    /*
     * REGLA OBLIGATORIA:
     * Temazcal se valida únicamente contra el ID almacenado en
     * el borrador. Nunca se cambia por el jacuzzi de Juárez.
     */
    const recursoTemazcal = idNormalizado(
      reserva.temazcal_recurso_id ??
      reserva.recurso_agua_asignado ??
      (reserva.recursos_agua_asignados_originales || [])[0] ??
      (reserva.recursos_agua_consulta || [])[0]
    );

    if (!recursoTemazcal) {
      throw new Error(
        'El borrador de Temazcal no contiene temazcal_recurso_id ' +
        'ni recurso_agua_asignado. No se creó ninguna cita.'
      );
    }

    const horariosTemazcal = horariosDelRecurso(
      mapaAgua,
      recursoTemazcal
    );

    diagnosticoAgua = {
      tipo: 'TEMAZCAL',
      recurso_solicitado: recursoTemazcal,
      fecha_solicitada: fechaAgua,
      hora_solicitada: horaAgua,
      ids_devueltos: idsDevueltos(mapaAgua),
      horarios_devueltos: horasDevueltas(horariosTemazcal),
    };

    if (horariosTemazcal === undefined) {
      throw new Error(
        'Pabau no devolvió el recurso de Temazcal ' + recursoTemazcal +
        ' para ' + fechaAgua + '. IDs devueltos: ' +
        (diagnosticoAgua.ids_devueltos.join(', ') || 'ninguno') +
        '. No se creó ninguna cita.'
      );
    }

    if (!contieneHora(horariosTemazcal, horaAgua)) {
      throw new Error(
        'El Temazcal ' + recursoTemazcal +
        ' no está disponible el ' + fechaAgua +
        ' a las ' + horaAgua + '. Horarios devueltos: ' +
        (diagnosticoAgua.horarios_devueltos.join(', ') || 'ninguno') +
        '. No se creó ninguna cita.'
      );
    }

    recursosSeleccionados = [recursoTemazcal];
  } else {
    const candidatosAgua = unicos([
      ...(reserva.recursos_agua_asignados_originales || []),
      ...(reserva.recursos_agua_candidatos || []),
      ...(reserva.recursos_agua_consulta || []),
    ]);

    if (reserva.sucursal === '24079') {
      const cantidad = Number(reserva.numero_personas || 1);

      if (cantidad <= 6) {
        if (disponibleAgua('151269')) recursosSeleccionados = ['151269'];
        else if (disponibleAgua('151302')) recursosSeleccionados = ['151302'];
      } else if (cantidad <= 12) {
        if (disponibleAgua('151302')) recursosSeleccionados = ['151302'];
      } else if (
        disponibleAgua('151269') &&
        disponibleAgua('151302')
      ) {
        recursosSeleccionados = ['151269', '151302'];
      }
    } else {
      recursosSeleccionados = candidatosAgua
        .filter(disponibleAgua)
        .slice(0, Number(reserva.jacuzzis_necesarios || 1));
    }

    diagnosticoAgua = {
      tipo: 'JACUZZI',
      recursos_solicitados: candidatosAgua,
      recursos_seleccionados: recursosSeleccionados,
      fecha_solicitada: fechaAgua,
      hora_solicitada: horaAgua,
      ids_devueltos: idsDevueltos(mapaAgua),
    };

    if (
      recursosSeleccionados.length <
      Number(reserva.jacuzzis_necesarios || 1)
    ) {
      throw new Error(
        'La disponibilidad cambió antes de crear la retención. ' +
        'Se necesitan ' + Number(reserva.jacuzzis_necesarios || 1) +
        ' recursos de jacuzzi a las ' + horaAgua +
        ' y Pabau devolvió: ' +
        (diagnosticoAgua.ids_devueltos.join(', ') || 'ninguno') +
        '. No se creó ninguna cita.'
      );
    }
  }
}

if (reserva.requiere_terapeuta) {
  const fechaMasaje = texto(reserva.masaje_inicio).slice(0, 10);
  const horaMasaje = texto(reserva.masaje_inicio).slice(11, 16);
  const mapaTerapeutas = mapaDeFecha(
    fechasTerapeutas,
    fechaMasaje
  );

  if (!mapaTerapeutas) {
    throw new Error(
      'Pabau no devolvió la fecha de masaje ' + fechaMasaje +
      '. No se creó ninguna cita.'
    );
  }

  const originales = unicos(reserva.terapeutas_ids || []);
  const permitidosRecibidos = unicos(
    reserva.terapeutas_permitidos || []
  );
  if(!permitidosRecibidos.length)throw Error('SIN_PERSONAL_VIGENTE_PARA_RETENER');
  const filtroPermitidos = new Set(permitidosRecibidos);

  const idsCandidatos = idsDevueltos(mapaTerapeutas);

  const disponibles = idsCandidatos.filter(id=>id!=='151614')
    .filter(
      (id) => filtroPermitidos.size === 0 || filtroPermitidos.has(id)
    )
    .filter((id) =>
      contieneHora(
        horariosDelRecurso(mapaTerapeutas, id),
        horaMasaje
      )
    )
    .sort();

  const conservados = originales.filter((id) => disponibles.includes(id));
  const reemplazos = disponibles.filter((id) => !conservados.includes(id));
  const necesarios = Number(reserva.terapeutas_necesarios || 0);

  terapeutasSeleccionados = [
    ...conservados,
    ...reemplazos,
  ].slice(0, necesarios);

  terapeutasReemplazados = originales.filter(
    (id) => !terapeutasSeleccionados.includes(id)
  );

  if (necesarios < 1 || terapeutasSeleccionados.length < necesarios) {
    throw new Error(
      'La disponibilidad cambió antes de crear la retención. ' +
      'Se necesitan ' + necesarios +
      ' terapeutas y solo hay ' + terapeutasSeleccionados.length +
      ' disponibles a las ' + horaMasaje +
      '. IDs disponibles: ' +
      (disponibles.join(', ') || 'ninguno') +
      '. No se creó ninguna cita.'
    );
  }
}

return [{
  json: {
    ...reserva,
    recursos_agua_asignados: recursosSeleccionados,
    recurso_agua_asignado: recursosSeleccionados[0] || null,
    diagnostico_revalidacion_agua: diagnosticoAgua,
    terapeutas_ids_originales: reserva.requiere_terapeuta
      ? unicos(reserva.terapeutas_ids || [])
      : [],
    terapeutas_ids: terapeutasSeleccionados,
    terapeutas_asignados: terapeutasSeleccionados.map((id) => ({
      id,
      hora: texto(reserva.masaje_inicio).slice(11, 16) || null,
    })),
    terapeutas_reemplazados: terapeutasReemplazados,
    hubo_reasignacion_terapeutas: terapeutasReemplazados.length > 0,
    disponibilidad_reconfirmada: true,
    revalidacion_agua_omitida: !reserva.requiere_agua,
    revalidacion_terapeutas_omitida: !reserva.requiere_terapeuta,
  },
}];

const d = $input.first().json;
return d.recursos_agua_asignados.map((employeeId, index) => ({
  json: {
    ...d,
    employee_id: employeeId,
    numero_recurso_agua: index + 1,
    start_time: d.jacuzzi_inicio.replace('T', ' ').slice(0, 16)
  }
}));

const reserva = $('Verificar disponibilidad para retención').first().json;
const respuestas = $input.all().map((item) => item.json);

function idCita(r){const b=r.body??r;const id=b.appointment_id??b.data?.appointment_id??b.data?.appointment?.id??b.appointment?.id??b.data?.id??b.id;return /^[1-9]\d*$/.test(String(id??''))?String(id):null;}
function exitosa(r){const b=r.body??r;return !r.error&&Number(r.statusCode)>=200&&Number(r.statusCode)<300&&b.success!==false&&b.status!=='error'&&!!idCita(r);}

/*
 * Respuesta INCIERTA: Pabau pudo crear la cita sin que nos llegara la confirmación.
 * Casos: timeout de red (ECONNABORTED), corte de conexión, error 5xx, o 2xx sin appointment_id.
 * En esos casos NO se puede saber si la cita existe, pero tampoco se abandona el masaje:
 * se continúa y al final el borrador queda en requiere_revision para verificación manual.
 */
function incierta(r){
  if(exitosa(r))return false;
  const codigo=String((r&&r.error&&(r.error.code||r.error.message))||'');
  const status=Number((r&&r.statusCode)||0);
  if(/ECONNABORTED|ETIMEDOUT|ECONNRESET|timeout|socket hang up/i.test(codigo))return true;
  if(status===0)return true;
  if(status>=500)return true;
  if(status>=200&&status<300)return true;
  return false;
}
function resumen(r){
  const codigo=String((r&&r.error&&(r.error.code||r.error.message))||'').slice(0,120);
  return {status:Number((r&&r.statusCode)||0),incierta:incierta(r),confirmada:exitosa(r),codigo:codigo||null};
}

const fallidas = respuestas.filter((respuesta) => !exitosa(respuesta));
const inciertas = fallidas.filter(incierta);
const definitivas = fallidas.filter((r) => !incierta(r));
const idsConfirmados = [...new Set(respuestas.filter(exitosa).map(idCita).filter(Boolean))];
const esperadas = Number(reserva.jacuzzis_necesarios || 0);
const completa = !fallidas.length
  && idsConfirmados.length === esperadas
  && new Set(idsConfirmados).size === idsConfirmados.length;

if (!completa && inciertas.length && !definitivas.length) {
  return [{
    json: {
      ...reserva,
      creacion_completa: true,
      creacion_agua_incierta: true,
      motivo_revision: 'CREACION_INCIERTA_PABAU_VERIFICAR_MANUAL',
      citas_agua_creadas: idsConfirmados.length,
      citas_agua_confirmadas: idsConfirmados.length,
      citas_agua_esperadas: esperadas,
      pabau_citas_agua_ids: idsConfirmados,
      pabau_citas_masaje_ids: [],
      respuestas_agua: respuestas.map(resumen)
    }
  }];
}

if (!completa) {
  return [{
    json: {
      ...reserva,
      creacion_completa: false,
      creacion_agua_incierta: false,
      citas_agua_confirmadas: idsConfirmados.length,
      citas_agua_esperadas: esperadas,
      pabau_citas_agua_ids: idsConfirmados,
      pabau_citas_masaje_ids: [],
      motivo_revision: 'CREACION_PARCIAL_O_INCIERTA_PABAU_AGUA_NO_REINTENTAR',
      respuestas_agua: respuestas.map(resumen)
    }
  }];
}

return [{
  json: {
    ...reserva,
    creacion_completa: true,
    creacion_agua_incierta: false,
    citas_agua_creadas: respuestas.length,
    citas_agua_confirmadas: idsConfirmados.length,
    citas_agua_esperadas: esperadas,
    pabau_citas_agua_ids: idsConfirmados,
    respuestas_agua: respuestas.map(resumen)
  }
}];

const d = $input.first().json;
if(!Array.isArray(d.terapeutas_ids)||d.terapeutas_ids.length!==Number(d.numero_personas||d.personas)||new Set(d.terapeutas_ids.map(String)).size!==d.terapeutas_ids.length)throw Error('NUMERO_TERAPEUTAS_NO_COINCIDE_CON_PERSONAS');
return d.terapeutas_ids.map((employeeId, index) => ({
  json: {
    ...d,
    employee_id: employeeId,
    numero_terapeuta: index + 1,
    start_time: d.masaje_inicio.replace('T', ' ').slice(0, 16)
  }
}));

const normalizada = $('Normalizar borrador para retención').first().json;
const base = normalizada.requiere_agua
  ? $('Consolidar agua retenida').first().json
  : $('Sin citas de agua').first().json;
const respuestas = $input.all().map((item) => item.json);

function idCita(r){const b=r.body??r;const id=b.appointment_id??b.data?.appointment_id??b.data?.appointment?.id??b.appointment?.id??b.data?.id??b.id;return /^[1-9]\d*$/.test(String(id??''))?String(id):null;}
function exitosa(r){const b=r.body??r;return !r.error&&Number(r.statusCode)>=200&&Number(r.statusCode)<300&&b.success!==false&&b.status!=='error'&&!!idCita(r);}
function incierta(r){
  if(exitosa(r))return false;
  const codigo=String((r&&r.error&&(r.error.code||r.error.message))||'');
  const status=Number((r&&r.statusCode)||0);
  if(/ECONNABORTED|ETIMEDOUT|ECONNRESET|timeout|socket hang up/i.test(codigo))return true;
  if(status===0)return true;
  if(status>=500)return true;
  if(status>=200&&status<300)return true;
  return false;
}
function resumen(r){
  const codigo=String((r&&r.error&&(r.error.code||r.error.message))||'').slice(0,120);
  return {status:Number((r&&r.statusCode)||0),incierta:incierta(r),confirmada:exitosa(r),codigo:codigo||null};
}

const fallidas = respuestas.filter((respuesta) => !exitosa(respuesta));
const inciertasMasaje = fallidas.filter(incierta);
const citasMasaje = [...new Set(respuestas.filter(exitosa).map(idCita).filter(Boolean))];
const citasAgua = Array.isArray(base.pabau_citas_agua_ids) ? base.pabau_citas_agua_ids.map(String) : [];
const jacuzzisEsperados = Number(base.jacuzzis_necesarios || 1);
const terapeutasEsperados = Number(base.terapeutas_necesarios || 0);
const aguaIncierta = base.creacion_agua_incierta === true;
const aguaIncompleta = normalizada.requiere_agua && citasAgua.length !== jacuzzisEsperados;
const idsTodos = [...citasAgua, ...citasMasaje];
const completa = !fallidas.length
  && !aguaIncierta
  && !aguaIncompleta
  && respuestas.length === terapeutasEsperados
  && citasMasaje.length === terapeutasEsperados
  && new Set(idsTodos).size === idsTodos.length
  && (!normalizada.requiere_agua || citasAgua.length === jacuzzisEsperados);

if (!completa) {
  const motivo = (aguaIncierta || inciertasMasaje.length)
