function spaNorm(v) {
  return String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/buddha|budhas|budas|buda\b/g, 'budha')
    .replace(/fulldayspa/g, 'full day spa').replace(/3\s*p(?:x|ax)\b/g, 'tribu')
