const seleccionada = $('Seleccionar borrador pendiente más reciente').first().json || {};

function canonClave(valor) {
  const texto = String(valor ?? '').trim();
  const match = texto.match(/^(\d{4}-\d{2}-\d{2})[T\s](\d{1,2}):(\d{2})/);
  if (!match) return texto;

  return (
    match[1] +
    'T' +
    String(Number(match[2])).padStart(2, '0') +
    ':' +
    match[3]
  );
}

function inicioClave(fila) {
  return canonClave(fila.masaje_inicio ?? fila.jacuzzi_inicio);
}

const candidatosEntrada = $input.all()
  .map((item) => item?.json)
  .filter(
