 const mod=servicio.split('_').pop(),ids=SPA_SAUNA_IDS[mod];
 if(sucursal!=='24079'||cantidadSolicitada!==({individual:1,pareja:2,tribu:3})[mod])throw new Error('Modalidad o sucursal de sauna no compatible');
 if(String(servicioAguaId)!==ids[0]||String(servicioTerapeutaId)!==ids[1])throw new Error('Los IDs del borrador no corresponden al servicio solicitado');
 if(recursosAguaRecibidos.length!==1||recursosAguaRecibidos[0]!=='151614')throw new Error('El borrador de sauna contiene un recurso diferente al 151614');
 if(masajeInicio!==sumarMinutos(jacuzziInicio,40))throw new Error('El masaje de Elephant Glow debe comenzar 40 minutos después del sauna');
 if(terapeutas.includes('151614'))throw new Error('El recurso sauna no puede asignarse como terapeuta');
